import fs from 'fs';
import os from 'os';
import path from 'path';

const dir = path.join(os.homedir(), '.dsh', 'storages', 'session_projcache', 'sessions');
const files = fs.readdirSync(dir).filter(f => f.startsWith('session-') && f.endsWith('.json'));
const rows = [];
for (const f of files) {
  let j;
  try { j = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')); } catch { continue; }
  const r = j.record?.rows || {};
  const sid = f.replace(/^session-/, '').slice(0, 8);
  const ss = r.sessionStats?.val || {};
  const title = r.title?.val || '';
  const tu = r.tokenUsage?.val?.totals || {};
  const ctx = r.contextActivity?.val?.days || {};
  let wallMs = 0;
  // pick most recent day wallMs
  const dayKeys = Object.keys(ctx).sort();
  if (dayKeys.length) wallMs = ctx[dayKeys[dayKeys.length - 1]].wallMs || 0;
  const created = j.record?.identity?.createdAt || 0;
  if (!ss.steps && !wallMs) continue;
  rows.push({
    sid, title: String(title).slice(0, 24),
    steps: ss.steps || 0, turns: ss.turns || 0,
    wallMin: +(wallMs / 60000).toFixed(1),
    llmMin: +((ss.llmMs || 0) / 60000).toFixed(1),
    toolMin: +((ss.toolMs || 0) / 60000).toFixed(1),
    ttftMin: +((ss.ttftMs || 0) / 60000).toFixed(1),
    decodeMin: +((ss.decodeMs || 0) / 60000).toFixed(1),
    toolCalls: (() => { let n = 0; for (const d of Object.values(ctx)) n += (d.toolCalls || 0); return n; })(),
    uncached: tu.uncachedInputTokens || 0,
    created,
  });
}
rows.sort((a, b) => b.wallMin - a.wallMin);
console.log('sid       wall   llm  tool  ttft  dec  steps tools 未命中  标题');
for (const x of rows.filter(r => r.wallMin >= 1)) {
  console.log(
    `${x.sid} ${String(x.wallMin).padStart(6)} ${String(x.llmMin).padStart(5)} ${String(x.toolMin).padStart(5)} ${String(x.ttftMin).padStart(5)} ${String(x.decodeMin).padStart(5)} ${String(x.steps).padStart(5)} ${String(x.toolCalls).padStart(5)} ${String(x.uncached).padStart(7)}  ${x.title}`
  );
}
const tot = rows.reduce((a, x) => a + x.wallMin, 0);
console.log(`\n合计 wallMin=${tot.toFixed(0)} 会话数(>=1min)=${rows.filter(r=>r.wallMin>=1).length}`);
// aggregate where time goes across all
const A = rows.reduce((a, x) => ({ wall: a.wall + x.wallMin, llm: a.llm + x.llmMin, tool: a.tool + x.toolMin, ttft: a.ttft + x.ttftMin, dec: a.dec + x.decodeMin }), { wall: 0, llm: 0, tool: 0, ttft: 0, dec: 0 });
console.log(`聚合: wall=${A.wall.toFixed(0)} llm=${A.llm.toFixed(0)} tool=${A.tool.toFixed(0)} ttft=${A.ttft.toFixed(0)} decode=${A.dec.toFixed(0)}`);
console.log(`占 wall: llm=${(A.llm/A.wall*100).toFixed(0)}% tool=${(A.tool/A.wall*100).toFixed(0)}% 其中 ttft 占 llm=${(A.ttft/A.llm*100).toFixed(0)}% decode 占 llm=${(A.dec/A.llm*100).toFixed(0)}%`);

