import fs from 'fs';
import os from 'os';
import path from 'path';

const dir = path.join(os.homedir(), '.dsh', 'storages', 'session_projcache', 'sessions');
const files = fs.readdirSync(dir).filter(f => f.startsWith('session-') && f.endsWith('.json'));
// TZ +8; today anchor
const DAY = 86400000;
const now = Date.now();
const tzoff = 8 * 3600000;
const todayStart = Math.floor((now + tzoff) / DAY) * DAY - tzoff;

const byDay = {};
const todayRows = [];
for (const f of files) {
  let j; try { j = JSON.parse(fs.readFileSync(path.join(dir, f), 'utf8')); } catch { continue; }
  const r = j.record?.rows || {};
  const created = j.record?.identity?.createdAt || 0;
  if (!created) continue;
  const ss = r.sessionStats?.val || {};
  const ctx = r.contextActivity?.val?.days || {};
  const dayKeys = Object.keys(ctx).sort();
  // attribute wallMs to the day keys present
  for (const dk of dayKeys) {
    const d = ctx[dk];
    if (!byDay[dk]) byDay[dk] = { wall: 0, n: 0, tool: 0 };
    byDay[dk].wall += (d.wallMs || 0) / 60000;
    byDay[dk].tool += (d.toolsMs || 0) / 60000;
    byDay[dk].n += 1;
  }
  // today = created within today
  if (created >= todayStart) {
    const dk = dayKeys[dayKeys.length - 1];
    const wall = dk ? (ctx[dk].wallMs || 0) : 0;
    const title = r.title?.val || '';
    let tc = 0; for (const d of Object.values(ctx)) tc += (d.toolCalls || 0);
    todayRows.push({ sid: f.replace(/^session-/, '').slice(0, 8), title: String(title).slice(0, 22),
      wallMin: +(wall / 60000).toFixed(1), llmMin: +((ss.llmMs || 0) / 60000).toFixed(1),
      toolMin: +((ss.toolMs || 0) / 60000).toFixed(1), ttftMin: +((ss.ttftMs || 0) / 60000).toFixed(1),
      steps: ss.steps || 0, toolCalls: tc });
  }
}
console.log('=== 按天 wall 汇总（分钟）===');
for (const dk of Object.keys(byDay).sort()) {
  const x = byDay[dk];
  if (x.wall < 30) continue;
  console.log(`${dk}  wall=${x.wall.toFixed(0).padStart(6)}min tool=${x.tool.toFixed(0).padStart(5)} sessions=${x.n}`);
}
console.log('\n=== 今日会话按耗时排序 (wall>=3min) ===');
todayRows.sort((a, b) => b.wallMin - a.wallMin);
for (const x of todayRows.filter(r => r.wallMin >= 3)) {
  console.log(`${x.sid} wall=${String(x.wallMin).padStart(5)} llm=${String(x.llmMin).padStart(5)} tool=${String(x.toolMin).padStart(5)} ttft=${String(x.ttftMin).padStart(5)} steps=${String(x.steps).padStart(4)} tools=${String(x.toolCalls).padStart(4)}  ${x.title}`);
}
const tw = todayRows.reduce((a, x) => a + x.wallMin, 0);
console.log(`\n今日会话 ${todayRows.length} 个, 合计 wall=${tw.toFixed(0)}min, wall>=3min 的 ${todayRows.filter(r=>r.wallMin>=3).length} 个占 ${todayRows.filter(r=>r.wallMin>=3).reduce((a,x)=>a+x.wallMin,0).toFixed(0)}min`);

import fs from 'fs';
import os from 'os';
import path from 'path';
import zlib from 'zlib';

function zstdDecompressAll(buf) {
  const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
  const idxs = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idxs.push(i);
  if (idxs.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString('utf8'); } catch { return ''; } }
  let out = '';
  for (let k = 0; k < idxs.length; k++) {
    const s = idxs[k], e = k + 1 < idxs.length ? idxs[k + 1] : buf.length;
    try { out += zlib.zstdDecompressSync(buf.subarray(s, e)).toString('utf8'); } catch { }
  }
  return out;
}

const sidArg = process.argv[2];
if (!sidArg) { console.log('usage: node .tmp-tool-audit.mjs <sidprefix>'); process.exit(0); }
const base = path.join(os.homedir(), '.dsh', 'sessions');
const encDirs = fs.readdirSync(base);
let target = null;
for (const d of encDirs) {
  const dd = path.join(base, d);
  if (!fs.statSync(dd).isDirectory()) continue;
  for (const s of fs.readdirSync(dd)) {
    if (s.startsWith('session-' + sidArg)) {
      const f = path.join(dd, s, 'session.v4.jsonl.zstd');
      if (fs.existsSync(f)) target = f;
    }
  }
}
if (!target) { console.log('not found'); process.exit(0); }
const txt = zstdDecompressAll(fs.readFileSync(target));
const lines = txt.split('\n').filter(Boolean);
const calls = {};
const results = [];
const events = [];
for (const ln of lines) {
  let ev; try { ev = JSON.parse(ln); } catch { continue; }
  events.push(ev);
}
function ts(ev) { return ev.time || ev.ts || ev.timestamp || (ev.data && (ev.data.time || ev.data.ts)) || null; }
// find tool/call and tool/result
let callMap = {}, callSeq = [];
for (const ev of events) {
  const t = ev.type || ev.event || ev.kind;
  if (!t) continue;
  if (/tool\/call/.test(t)) {
    const d = ev.data || ev;
    const callId = d.callId || d.id || (d.message && d.message.callId);
    const name = d.name || d.toolName || (d.message && d.message.name) || '?';
    callMap[callId] = { name, t: ts(ev), seq: ev.seq };
    callSeq.push(callId);
  } else if (/tool\/result/.test(t)) {
    const d = ev.data || ev;
    const callId = d.toolCallId || (d.message && d.message.toolCallId);
    results.push({ callId, t: ts(ev), seq: ev.seq });
  }
}
// compute durations
const byTool = {};
let total = 0, n = 0, missingT = 0;
for (const r of results) {
  const c = callMap[r.callId];
  if (!c) continue;
  if (!c.t || !r.t) { missingT++; continue; }
  let dur = r.t - c.t;
  if (dur < 0) dur = 0;
  byTool[c.name] = byTool[c.name] || { count: 0, ms: 0, max: 0, over5s: 0 };
  const b = byTool[c.name];
  b.count++; b.ms += dur; total += dur; n++;
  if (dur > b.max) b.max = dur;
  if (dur > 5000) b.over5s++;
}
console.log(`session ${sidArg}: tool calls=${callSeq.length} results=${results.length} paired=${n} missingTs=${missingT} totalToolSec=${(total/1000).toFixed(0)}`);
console.log('by tool (sorted by total ms):');
for (const [name, b] of Object.entries(byTool).sort((a, b) => b[1].ms - a[1].ms)) {
  console.log(`  ${name.padEnd(22)} n=${String(b.count).padStart(3)} total=${(b.ms/1000).toFixed(1).padStart(7)}s avg=${(b.ms/b.count/1000).toFixed(2)}s max=${(b.max/1000).toFixed(1)}s over5s=${b.over5s}`);
}

import fs from 'fs';
import os from 'os';
import path from 'path';
import zlib from 'zlib';

function zstdDecompressAll(buf) {
  const MAGIC = Buffer.from([0x28, 0xb5, 0x2f, 0xfd]);
  const idxs = [];
  for (let i = 0; (i = buf.indexOf(MAGIC, i)) >= 0; i += 4) idxs.push(i);
  if (idxs.length <= 1) { try { return zlib.zstdDecompressSync(buf).toString('utf8'); } catch { return ''; } }
  let out = '';
  for (let k = 0; k < idxs.length; k++) {
    const s = idxs[k], e = k + 1 < idxs.length ? idxs[k + 1] : buf.length;
    try { out += zlib.zstdDecompressSync(buf.subarray(s, e)).toString('utf8'); } catch { }
  }
  return out;
}

// sessions created today
const cacheDir = path.join(os.homedir(), '.dsh', 'storages', 'session_projcache', 'sessions');
const DAY = 86400000, tzoff = 8 * 3600000;
const now = Date.now();
const todayStart = Math.floor((now + tzoff) / DAY) * DAY - tzoff;
const todaySids = new Set();
for (const f of fs.readdirSync(cacheDir)) {
  if (!f.endsWith('.json')) continue;
  try { const j = JSON.parse(fs.readFileSync(path.join(cacheDir, f), 'utf8')); if ((j.record?.identity?.createdAt || 0) >= todayStart) todaySids.add(f.replace(/^session-/, '').slice(0, 8)); } catch { }
}
// map sid -> log file
const base = path.join(os.homedir(), '.dsh', 'sessions');
const logMap = {};
for (const d of fs.readdirSync(base)) {
  const dd = path.join(base, d); if (!fs.statSync(dd).isDirectory()) continue;
  for (const s of fs.readdirSync(dd)) {
    const p = path.join(dd, s, 'session.v4.jsonl.zstd');
    if (fs.existsSync(p)) logMap[s.replace(/^session-/, '').slice(0, 8)] = p;
  }
}

const agg = { orchestrate: { n: 0, ms: 0, timeout300: 0, over120: 0 }, ask_user_question: { n: 0, ms: 0 }, job_output: { n: 0, ms: 0 } };
const perSession = [];
for (const sid of todaySids) {
  const f = logMap[sid]; if (!f) continue;
  let events = []; try { events = zstdDecompressAll(fs.readFileSync(f)).split('\n').filter(Boolean).map(l => { try { return JSON.parse(l); } catch { return null; } }).filter(Boolean); } catch { continue; }
  const callMap = {}; const results = [];
  for (const ev of events) {
    const t = ev.type || ev.event || ev.kind;
    const d = ev.data || {};
    const tt = ev.time || ev.ts || ev.timestamp || d.time || d.ts;
    if (/tool\/call/.test(t || '')) { const id = d.callId || d.id; callMap[id] = { name: d.name || d.toolName || '?', t: tt }; }
    else if (/tool\/result/.test(t || '')) { results.push({ id: d.toolCallId || (d.message && d.message.toolCallId), t: tt }); }
  }
  let oMs = 0, oN = 0, o300 = 0, o120 = 0, aMs = 0, aN = 0, jMs = 0, jN = 0;
  for (const r of results) {
    const c = callMap[r.id]; if (!c || !c.t || !r.t) continue;
    const dur = Math.max(0, r.t - c.t);
    if (c.name === 'orchestrate') { oMs += dur; oN++; if (dur >= 295000) o300++; if (dur > 120000) o120++; }
    else if (c.name === 'ask_user_question') { aMs += dur; aN++; }
    else if (c.name === 'job_output') { jMs += dur; jN++; }
  }
  agg.orchestrate.n += oN; agg.orchestrate.ms += oMs; agg.orchestrate.timeout300 += o300; agg.orchestrate.over120 += o120;
  agg.ask_user_question.n += aN; agg.ask_user_question.ms += aMs;
  agg.job_output.n += jN; agg.job_output.ms += jMs;
  if (oMs > 60000 || aMs > 120000 || jMs > 60000) perSession.push({ sid, oMin: +(oMs / 60000).toFixed(1), oN, o300, aMin: +(aMs / 60000).toFixed(1), aN, jMin: +(jMs / 60000).toFixed(1), jN });
}
